79a4","ti":"Edição","i":1},{"t":"6ac01ac47df4f22dbe451b89","k":"6ac01ac47df4f22dbe451bbd","ti":"Copy","i":0},{"t":"6ac01ac47df4f22dbe451b89","k":"6ac01ac47df4f22dbe451bbf","ti":"Edição","i":1},{"t":"6ab41d78e353ee5af7adec94","k":"6ab41d78e353ee5af7adecae","ti":"Copy","i":0},{"t":"6ab41d78e353ee5af7adec94","k":"6ab41d78e353ee5af7adecac","ti":"Edição","i":1},{"t":"6ab5642563a0dbb1e2c4cbe1","k":"6ab5642563a0dbb1e2c4cbfb","ti":"Copy","i":0},{"t":"6ab5642563a0dbb1e2c4cbe1","k":"6ab5642563a0dbb1e2c4cbf9","ti":"Edição","i":1},{"t":"6a7541d9ee26452784107f5e","k":"6a7541d9ee26452784107fae","ti":"Copy","i":0},{"t":"6a7541d9ee26452784107f5e","k":"6a7541d9ee26452784107fb0","ti":"Edição","i":1},{"t":"6a712ae7e35c5865a5a22e8d","k":"6a712ae7e35c5865a5a22f14","ti":"Copy","i":0},{"t":"6a712ae7e35c5865a5a22e8d","k":"6a712ae7e35c5865a5a22f16","ti":"Edição","i":1},{"t":"6abfcf13e65b2cc65876c2fd","k":"6abfcf13e65b2cc65876c32f","ti":"Copy","i":0},{"t":"6abfcf13e65b2cc65876c2fd","k":"6abfcf13e65b2cc65876c32d","ti":"Edição","i":1},{"t":"6ae02542d0dffe5e34e80f7b","k":"6ae02542d0dffe5e34e80f9c","ti":"Copy","i":0},{"t":"6ae02542d0dffe5e34e80f7b","k":"6ae02542d0dffe5e34e80f9e","ti":"Edição","i":1}],"its":[]}$dados$::jsonb;
  v_standby uuid;
  v_criacao uuid;
  v_ofertas jsonb := '{}';
  o record;
  v_id uuid;
  v_irma record;
  c record;
  v_card uuid;
  v_lista uuid;
  v_check uuid;
  k record;
  v_novos int := 0;
begin
  perform set_config('ops.silencio', '1', true);

  select id into v_standby from ops.listas where nome ilike 'standby%' order by arquivada, ordem limit 1;
  select id into v_criacao from ops.listas where nome ilike 'cria%' order by arquivada, ordem limit 1;
  if v_standby is null or v_criacao is null then
    raise exception 'Listas "Standby" ou "Criação" não encontradas.';
  end if;

  -- Ofertas: acha pela sigla ou pelo nome no idioma; cria se faltar
  for o in
    select * from (values
      ('PC-EN', 'PC', 'EN', 'Pontos de Comando', '%pontos de comando%'),
      ('PC-FR', 'PC', 'FR', 'Pontos de Comando', '%pontos de comando%'),
      ('PC-IT', 'PC', 'IT', 'Pontos de Comando', '%pontos de comando%'),
      ('GE-EN', 'GE', 'EN', 'Gatilhos de Esguicho', '%gatilhos%')
    ) as t(chave, codigo, idioma, nome, busca)
  loop
    select id into v_id from ops.ofertas
     where idioma = o.idioma and (codigo = o.codigo or nome ilike o.busca)
     order by (codigo = o.codigo) desc limit 1;
    if v_id is null then
      select nome, cor into v_irma from ops.ofertas
       where codigo = o.codigo or nome ilike o.busca order by criado_em limit 1;
      insert into ops.ofertas (nome, codigo, idioma, cor, status)
      values (coalesce(v_irma.nome, o.nome), o.codigo, o.idioma, v_irma.cor, 'em_producao')
      returning id into v_id;
    end if;
    v_ofertas := v_ofertas || jsonb_build_object(o.chave, v_id);
  end loop;

  create temp table _mapa (t text primary key, card_id uuid) on commit drop;

  -- Cards, na ordem do Trello
  for c in
    select * from jsonb_to_recordset(dados -> 'cards') as x(
      t text, o text, l text, tipo text, ad int, h int, m int, f text, nome text, d text,
      due timestamptz, cr timestamptz, ld timestamptz, n int)
    order by n
  loop
    v_lista := case c.l when 'standby' then v_standby else v_criacao end;
    v_card := null;

    if c.tipo = 'ad' then
      insert into ops.cards (oferta_id, lista_id, tipo, formato, ad_num, hook_num, var_num, nome,
                             descricao, prazo, criado_em, lista_desde)
      values ((v_ofertas ->> c.o)::uuid, v_lista, 'ad', c.f, c.ad, c.h, c.m, '-', c.d, c.due, c.cr, c.ld)
      on conflict (oferta_id, ad_num, hook_num, var_num) where tipo = 'ad' do nothing
      returning id into v_card;
    elsif not exists (select 1 from ops.cards
                       where oferta_id = (v_ofertas ->> c.o)::uuid and tipo = c.tipo and nome = c.nome) then
      insert into ops.cards (oferta_id, lista_id, tipo, nome, descricao, prazo, criado_em, lista_desde)
      values ((v_ofertas ->> c.o)::uuid, v_lista, c.tipo, c.nome, c.d, c.due, c.cr, c.ld)
      returning id into v_card;
    end if;

    if v_card is not null then
      insert into _mapa values (c.t, v_card);
      v_novos := v_novos + 1;
    end if;
  end loop;

  -- Anexos de link
  insert into ops.anexos (card_id, titulo, url, ordem)
  select mp.card_id, a.ti, a.u, a.i
  from jsonb_to_recordset(dados -> 'an') as a(t text, ti text, u text, i int)
  join _mapa mp on mp.t = a.t;

  -- Checklists e itens
  for k in
    select mp.card_id, x.k, x.ti, x.i
    from jsonb_to_recordset(dados -> 'cls') as x(t text, k text, ti text, i int)
    join _mapa mp on mp.t = x.t
  loop
    insert into ops.checklists (card_id, titulo, ordem) values (k.card_id, k.ti, k.i) returning id into v_check;
    insert into ops.checklist_itens (checklist_id, texto, feito, ordem)
    select v_check, it.tx, it.f, it.i
    from jsonb_to_recordset(dados -> 'its') as it(k text, tx text, f boolean, i int)
    where it.k = k.k;
  end loop;

  -- Uma linha no histórico de cada card importado
  perform set_config('ops.silencio', '0', true);
  for c in
    select mp.card_id, l.nome as lista
    from _mapa mp join ops.cards cc on cc.id = mp.card_id join ops.listas l on l.id = cc.lista_id
  loop
    perform ops.registrar(c.card_id, 'importado_trello', 'importou do Trello (' || c.lista || ')');
  end loop;

  raise notice 'Cards importados agora: %', v_novos;
end $imp$;

-- Conferência: na primeira vez, PC-EN deve ganhar 78 em Standby e 4 em Criação;
-- GE-EN 4, PC-FR 1 e PC-IT 1 em Standby.
select o.codigo || '-' || o.idioma as oferta, l.nome as lista, count(*) as cards,
       count(*) filter (where exists (select 1 from ops.anexos a where a.card_id = c.id)) as com_anexos
from ops.cards c
join ops.ofertas o on o.id = c.oferta_id
join ops.listas l on l.id = c.lista_id
where exists (select 1 from ops.atividades a where a.card_id = c.id and a.tipo = 'importado_trello')
group by 1, 2 order by 1, 2;
